// =========================================================
// TRANSLATION HELPER FUNCTIONS
// =========================================================

function t(key, lang) {
    lang = lang || getCurrentLanguage();
    if (!translations[lang]) lang = 'ar';
    return translations[lang][key] || translations['en'][key] || key;
}

function setLanguage(lang) {
    if (!translations[lang]) {
        console.warn('Language ' + lang + ' not found, falling back to English.');
        lang = 'en';
    }

    localStorage.setItem('socialwiki_lang', lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = (lang === 'ar' || lang === 'he') ? 'rtl' : 'ltr';

    document.querySelectorAll('[data-i18n]').forEach(function (el) {
        var key = el.getAttribute('data-i18n');
        var translated = t(key, lang);

        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
            el.placeholder = translated;
        } else {
            el.textContent = translated;
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(function (el) {
        var key = el.getAttribute('data-i18n-placeholder');
        el.placeholder = t(key, lang);
    });

    document.querySelectorAll('[data-i18n-title]').forEach(function (el) {
        var key = el.getAttribute('data-i18n-title');
        el.title = t(key, lang);
    });

    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang: lang } }));
}

function getCurrentLanguage() {
    return localStorage.getItem('socialwiki_lang') || 'ar';
}

function initLanguage() {
    var savedLang = getCurrentLanguage();
    setLanguage(savedLang);
}

if (typeof window !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLanguage);
    } else {
        initLanguage();
    }
}

function applyTranslations() {
    if (typeof getCurrentLanguage !== 'function') return;
    if (typeof setLanguage !== 'function') return;
    setLanguage(getCurrentLanguage());
}

function changeLanguage(lang) {
    if (typeof setLanguage === 'function') {
        setLanguage(lang);
    }
    var menu = document.getElementById('languageMenu');
    if (menu) menu.style.display = 'none';
}

function toggleLanguageMenu() {
    var menu = document.getElementById('languageMenu');
    if (!menu) return;
    menu.style.display = (menu.style.display === 'none' || menu.style.display === '') 
        ? 'block' 
        : 'none';
}

if (typeof window !== 'undefined') {
    window.addEventListener('click', function (e) {
        var menu = document.getElementById('languageMenu');
        var btn = document.getElementById('languageButton');
        if (menu && btn && !btn.contains(e.target) && !menu.contains(e.target)) {
            menu.style.display = 'none';
        }
    });
}